package stack

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"os"
	"path/filepath"
	"strings"

	"github.com/Alfredo-capitia/Orvyn/internal/config"
)

// ProjectNamePrefix prefixes project names generated by Orvyn.
const ProjectNamePrefix = "orvyn-"

// ProjectName returns the Compose project that owns the stack described by cfg.
//
// The name is pinned in the generated compose file (the top-level "name:" key)
// so that every Compose invocation targets the same project regardless of the
// current working directory. When the file predates that key, the name Compose
// would have derived from the stack directory is returned instead: pinning a
// new name there would orphan the containers that are already running.
func ProjectName(cfg *config.Config) string {
	if cfg == nil || cfg.StackDir == "" {
		return legacyProjectName("orvyn")
	}
	data, err := os.ReadFile(cfg.StackCompose())
	if err == nil {
		if name := ComposeProjectName(data); name != "" {
			return name
		}
		return legacyProjectName(cfg.StackDir)
	}
	if os.IsNotExist(err) {
		return DefaultProjectName(cfg.StackDir)
	}
	// The file exists but cannot be read. Fall back to the legacy name, which
	// is what Compose would use, rather than pinning a new, empty project.
	return legacyProjectName(cfg.StackDir)
}

// DefaultProjectName derives a stable, unique project name from the absolute
// stack directory. Using a hash keeps the name valid for Compose and avoids
// collisions between users whose stack directories share a base name, such as
// "stack".
func DefaultProjectName(stackDir string) string {
	abs, err := filepath.Abs(stackDir)
	if err != nil {
		abs = stackDir
	}
	sum := sha256.Sum256([]byte(filepath.Clean(abs)))
	return ProjectNamePrefix + hex.EncodeToString(sum[:4])
}

// ComposeProjectName extracts the top-level "name:" key from a Compose file.
// It returns an empty string when the key is absent or invalid, so a malformed
// or hostile value cannot be turned into a Compose project name.
func ComposeProjectName(data []byte) string {
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" || line[0] == ' ' || line[0] == '\t' || line[0] == '#' {
			continue
		}
		key, value, ok := strings.Cut(line, ":")
		if !ok || strings.TrimSpace(key) != "name" {
			continue
		}
		value = strings.TrimSpace(value)
		if i := strings.Index(value, " #"); i >= 0 {
			value = strings.TrimSpace(value[:i])
		}
		value = strings.Trim(value, `"'`)
		if isValidProjectName(value) {
			return value
		}
		return ""
	}
	return ""
}

// ComposeArgs builds the docker arguments for a Compose invocation against the
// Orvyn stack. Pinning the project with -p makes the command independent of
// the working directory and of any COMPOSE_PROJECT_NAME in the environment.
func ComposeArgs(cfg *config.Config, args ...string) []string {
	out := []string{"compose", "-p", ProjectName(cfg), "-f", cfg.StackCompose()}
	return append(out, args...)
}

// isValidProjectName reports whether name is a valid Compose project name.
func isValidProjectName(name string) bool {
	if name == "" || len(name) > 63 {
		return false
	}
	for i, r := range name {
		switch {
		case r >= 'a' && r <= 'z':
		case r >= '0' && r <= '9':
		case r == '-' || r == '_':
			if i == 0 {
				return false
			}
		default:
			return false
		}
	}
	return true
}

// legacyProjectName mirrors the project name Compose derives from the stack
// directory for installations created before the name was pinned: the directory
// base name, lowercased, with characters Compose does not allow removed.
func legacyProjectName(stackDir string) string {
	base := strings.ToLower(filepath.Base(filepath.Clean(stackDir)))
	var b strings.Builder
	for _, r := range base {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' || r == '_' {
			b.WriteRune(r)
		}
	}
	name := strings.TrimLeft(b.String(), "-_")
	if !isValidProjectName(name) {
		return "orvyn"
	}
	return name
}
